<?php
namespace App\Http\Controllers;
use App\Models\{Journal,Account,Currency};use App\Services\JournalService;use Illuminate\Http\Request;
class JournalController {public function index(){return view('journals.index',['journals'=>Journal::forCompany(auth()->user()->company_id)->latest('entry_date')->paginate(50)]);}public function create(){return view('journals.create',['accounts'=>Account::forCompany(auth()->user()->company_id)->where('active',1)->where('is_postable',1)->orderBy('code')->get(),'currencies'=>Currency::where('active',1)->get()]);}public function store(Request $r){$d=$r->validate(['entry_date'=>'required|date','description'=>'nullable|string|max:1000','lines'=>'required|array|min:2','lines.*.account_id'=>'required|integer','lines.*.debit'=>'nullable|decimal:0,3','lines.*.credit'=>'nullable|decimal:0,3']);$j=app(JournalService::class)->createDraft($r->user()->company_id,$r->user()->id,$d['entry_date'],$d['description']??null,$d['lines']);return redirect()->route('journals.show',$j);}public function show(Journal $journal){return view('journals.show',['journal'=>$journal->load('lines.account')]);}public function post(Journal $journal){app(JournalService::class)->post($journal,auth()->id());return back()->with('ok','Journal posted.');}public function reverse(Request $r,Journal $journal){$d=$r->validate(['date'=>'required|date','reason'=>'required|string|max:1000']);$rev=app(JournalService::class)->reverse($journal,$r->user()->id,$d['date'],$d['reason']);return redirect()->route('journals.show',$rev)->with('ok','Reversal posted.');}}
